export interface VaultImportResult {
    imported: CredentialMeta[];
    skipped:  Skipped[];
}

export interface Skipped {
    reason: string;
    row:    number;
}

export interface VaultListParams {
    kind?: CredentialKind;
}

export interface VaultListResult {
    credentials: CredentialMeta[];
}

export interface VaultLockResult {
    status: VaultStatus;
}

export interface VaultLockedPayload {
    reason: VaultLockedPayloadReason;
    status: VaultStatus;
}

export type VaultLockedPayloadReason = "manual" | "idle" | "sleep" | "screen_lock" | "shutdown";

export interface VaultSetupParams {
    slot: Slot;
}

export type Slot = "keychain" | "safe_storage" | "key_file";

export interface VaultSetupResult {
    recoveryKey: string;
    status:      VaultStatus;
}

export interface VaultStatusResult {
    status: VaultStatus;
}

export interface VaultUnlockParams {
    reason:       string;
    recoveryKey?: string;
}

export interface VaultUnlockResult {
    status: VaultStatus;
}

export interface VaultUnlockedPayload {
    status: VaultStatus;
    via:    VaultKeySlot;
}

export interface VaultUpdateParams {
    bindings?:           CredentialBinding[];
    credentialId:        string;
    name?:               string;
    requireAuthEachUse?: boolean;
    secret?:             CredentialSecretInput;
}

export interface VaultUpdateResult {
    credential: CredentialMeta;
}

export interface VaultUsesParams {
    credentialId: string;
    limit?:       number;
}

export interface VaultUsesResult {
    uses: CredentialUse[];
}

export interface CredentialUse {
    approvalId?:  null | string;
    createdAt:    string;
    credentialId: string;
    executor:     Executor;
    id:           string;
    outcome:      Outcome;
    reason?:      null | string;
    target:       string;
    taskId?:      null | string;
}

export type Executor = "browser" | "connector" | "sandbox" | "ssh";

export type Outcome = "filled" | "denied" | "failed";

export interface ViewCommandPayload {
    args:       { [key: string]: unknown };
    command:    ViewCommandName;
    commandId?: string;
}

export type ViewCommandName = "open" | "close" | "focus";

export interface ViewLayoutResult {
    layout?: ViewLayout | null;
}

export interface ViewLayout {
    focusedPaneId?: null | string;
    panes:          ViewPaneState[];
    updatedAt:      string;
}

export interface ViewPaneState {
    pane:      ViewPane;
    paneId:    string;
    placement: ViewPlacement;
    target?:   null | string;
    threadId?: null | string;
}

export type ViewPane = "chat" | "browser" | "terminal" | "files" | "editor" | "diff" | "plan" | "tasks" | "subagents" | "artifact" | "vm";

export type ViewPlacement = "main" | "side" | "split";

export interface ViewOpenParams {
    artifactId?: string;
    pane:        ViewPane;
    placement?:  ViewPlacement;
    /**
     * Pane-specific target: tab id, workspace path, artifact id
     */
    target?:   string;
    taskId?:   string;
    threadId?: string;
}

export interface ViewOpenResult {
    commandId: string;
}

/**
 * Either paneId or pane (the most recent pane of that kind)
 */
export interface ViewPaneRef {
    pane?:   ViewPane;
    paneId?: string;
}

export interface ViewReportParams {
    layout: ViewLayout;
}

export interface VoiceCancelParams {
    sessionId: string;
}

export interface VoiceEndedPayload {
    error?:    ErrorPayload;
    reason:    VoiceEndReason;
    sessionId: string;
}

export type VoiceEndReason = "stopped" | "cancelled" | "timeout" | "error";

export interface VoiceMemoSaveParams {
    sessionId: string;
    task?:     MemoTaskMode;
    threadId?: string;
}

export type MemoTaskMode = "auto" | "always" | "never";

export interface VoiceMemoSaveResult {
    /**
     * Quoted transcript, file and task blocks for the message that carries the memo
     */
    blocks:     Block[];
    content:    VoiceMemoContent;
    durationMs: number;
    item:       LibraryItem;
    provenance: Provenance;
    task?:      Task | null;
    transcript: Transcript;
}

export interface VoiceMemoContent {
    /**
     * Which patterns matched (override, secrecy, …)
     */
    flags: string[];
    /**
     * The memo reads like instructions to the agent; shown as a note, not obeyed
     */
    instructionLike: boolean;
    /**
     * URL-like strings in the memo; never fetched
     */
    urls: string[];
}

export interface Transcript {
    language?: string;
    segments:  TranscriptSegment[];
    text:      string;
}

export interface TranscriptSegment {
    confidence?: number;
    endMs:       number;
    /**
     * false = volatile partial a later segment replaces
     */
    final:   boolean;
    startMs: number;
    text:    string;
}

export interface VoicePushParams {
    /**
     * Base64 PCM in the session format
     */
    audio: string;
    /**
     * 0, 1, 2… per session; out of order is rejected
     */
    seq:       number;
    sessionId: string;
}

export interface VoiceSegmentPayload {
    segment:   TranscriptSegment;
    sessionId: string;
}

export interface VoiceStartParams {
    format: AudioFormat;
    /**
     * BCP 47
     */
    language?: string;
    /**
     * Keep the audio so voice.memo.save can file the session as a voice memo
     */
    memo?:     boolean;
    threadId?: string;
    /**
     * Extra terms; merged with the agent name, contacts and recent topics
     */
    vocabulary?: string[];
}

export interface VoiceStartResult {
    engine:    string;
    location:  SpeechEngineLocation;
    sessionId: null | string;
}

export interface VoiceStopParams {
    sessionId: string;
}

export interface VoiceStopResult {
    transcript: Transcript;
}

export interface WrapUpBlock {
    actions?: WrapUpAction[];
    ask?:     string;
    recap:    string;
    type:     WrapUpBlockType;
}

export type WrapUpBlockType = "wrap_up";
